SELECT EXTRACT(YEAR FROM pickup_at) AS year, EXTRACT(MONTH FROM pickup_at) AS month, EXTRACT(DAY FROM pickup_at) AS day, EXTRACT(HOUR FROM pickup_at) AS hour, EXTRACT(MINUTE FROM pickup_at) AS minute, EXTRACT(QUARTER FROM pickup_at) AS quarter, EXTRACT(WEEK FROM pickup_at) AS week, EXTRACT(DOW FROM pickup_at) AS day_of_week FROM stg_nyc_taxi_trips LIMIT 1000 UNION ALL SELECT EXTRACT(YEAR FROM ordered_at) AS year, EXTRACT(MONTH FROM ordered_at) AS month, EXTRACT(DAY FROM ordered_at) AS day, EXTRACT(HOUR FROM ordered_at) AS hour, EXTRACT(MINUTE FROM ordered_at) AS minute, EXTRACT(QUARTER FROM ordered_at) AS quarter, EXTRACT(WEEK FROM ordered_at) AS week, EXTRACT(DOW FROM ordered_at) AS day_of_week FROM stg_ecommerce_orders LIMIT 1000